CREATE TEMPORARY VIEW exp_group_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
    ,device_id
    ,platform
    ,is_ads
    ,feature_detail
    ,scenario_tag

    ,imp_cnt
    ,click_cnt
    ,view_cnt
    ,item_imp_cnt
    ,item_click_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,atc_same_day_gmv
    ,atc_within_3day_gmv
